__device__ __forceinline__ int64_t kv_offset(int page,int head,int token,int feature){return int64_t(128)*64*(head+2*page)+int64_t(128)*token+feature;}
__global__ void standalone(const __nv_bfloat16* q,const __nv_bfloat16*k,const __half*v,__nv_bfloat16*out,const int*table,int t){int tid=threadIdx.x,warp=tid>>5,lane=tid&31,h=blockIdx.y,kvh=h/6,row0=blockIdx.x*32,valid=min(32,t-row0);extern __shared__ __align__(128) unsigned char raw[];auto&s=*reinterpret_cast<SmemLayout*>(raw);for(int i=tid;i<valid*128;i+=512){int r=i/128,d=i%128;s.q[r*128+d]=__float2half_rn(__bfloat162float(q[(row0+r)*12*128+h*128+d]));}if(tid<32){s.row_max[tid]=-1.e30f;s.row_sum[tid]=0;}for(int i=tid;i<32*128;i+=512)s.o[i]=0;__syncthreads();for(int start=0;start<t;start+=176){int nk=min(176,t-start);for(int i=tid;i<nk*128;i+=512){int r=i/128,d=i%128,pos=start+r,page=table[pos>>6];s.reuse_kv.k[r*128+d]=__float2half_rn(__bfloat162float(k[kv_offset(page,kvh,pos&63,d)]));}__syncthreads();int nm=(valid+15)/16,nn=(nk+15)/16,total=nm*nn,per=(total+15)/16;unsigned rc=(lane&1)+((lane>>2)&1)*8+((lane>>4)&1)*4,cc=((lane>>1)&1)*2+((lane>>3)&1)*8;for(int ti=0;ti<per;++ti){int z=warp*per+ti;if(z>=total)break;int tm=z/nn*16,tn=z%nn*16;fragment<matrix_a,16,16,16,half,row_major>a;fragment<matrix_b,16,16,16,half,col_major>b;fragment<accumulator,16,16,16,float>acc;fill_fragment(acc,0);for(int kt=0;kt<8;++kt){load_matrix_sync(a,s.q+tm*128+kt*16,128);load_matrix_sync(b,s.reuse_kv.k+tn*128+kt*16,128);mma_sync(acc,a,b,acc);}for(int j=0;j<acc.num_elements;++j){int c=cc+(j&1)+((j>>2)&1)*4,r=rc+((j>>1)&1)*2,gm=row0+tm+r,gn=start+tn+c;acc.x[j]=(gm<row0+valid&&gn<start+nk&&gn<=gm)?acc.x[j]/sqrtf(128.f):-1.e30f;}store_matrix_sync(s.reuse_sp.s+tm*176+tn,acc,176,mem_row_major);}__syncthreads();int pvper=1;for(int sub=0;sub<nk;sub+=176){int nv=min(176,nk-sub),r=tid/16,tr=tid%16;__half*p=s.reuse_sp.p+r*176;int vc=nv>>2,vecs=(vc+15)/16,tail=vc<<2;float de=1;__half2 hb[20];int tc=-1;__half tv=__float2half(0);if(tid<valid*16){unsigned mask=valid==32?0xffffffffu:__activemask();int leader=__ffs(mask)-1;float*score=s.reuse_sp.s+r*176+sub;float mx=-1.e30f;float4*s4=(float4*)score;for(int j=0;j<vecs;++j){int c=tr+j*16;if(c<vc){float4 z=s4[c];mx=fmaxf(mx,fmaxf(fmaxf(z.x,z.y),fmaxf(z.z,z.w)));}}for(int c=tail+tr;c<nv;c+=16)mx=fmaxf(mx,score[c]);for(int o=8;o;o>>=1)mx=fmaxf(mx,__shfl_down_sync(mask,mx,o,16));float rm=__shfl_sync(mask,mx,leader,16),old=s.row_max[r],nm=fmaxf(old,rm);de=__expf(old-nm);float sum=0;int ix=0,base=tr;for(int j=0;j<vecs;++j,base+=16)if(base<vc){float4 z=s4[base];float e0=__expf(fmaxf(z.x-nm,-80.f)),e1=__expf(fmaxf(z.y-nm,-80.f)),e2=__expf(fmaxf(z.z-nm,-80.f)),e3=__expf(fmaxf(z.w-nm,-80.f));sum+=e0+e1+e2+e3;hb[ix++]=__float22half2_rn(make_float2(e0,e1));hb[ix++]=__float22half2_rn(make_float2(e2,e3));}for(int c=tail+tr;c<nv;c+=16){float e=__expf(fmaxf(score[c]-nm,-80.f));sum+=e;tc=c;tv=__float2half(e);}for(int o=8;o;o>>=1)sum+=__shfl_down_sync(mask,sum,o,16);float rs=__shfl_sync(mask,sum,leader,16);if(tr==0){s.row_sum[r]=de*s.row_sum[r]+rs;s.row_max[r]=nm;}}__syncthreads();if(tid<valid*16){int ix=0,base=tr;for(int j=0;j<vecs;++j,base+=16)if(base<vc){int c=base*4;reinterpret_cast<__half2*>(p+c)[0]=hb[ix++];reinterpret_cast<__half2*>(p+c)[1]=hb[ix++];}if(tc>=0)p[tc]=tv;for(int c=tail+tr;c<176;c+=16)if(c>=nv)p[c]=__float2half(0);if(start+sub>0)for(int d=tr;d<32;d+=16){float4*z=(float4*)(s.o+r*128);z[d/4]=make_float4(z[d/4].x*de,z[d/4].y*de,z[d/4].z*de,z[d/4].w*de);}}__syncthreads();for(int d=tid;d<32*128;d+=512){int r=d/128,c=d%128;float a=0;for(int x=0;x<nv;++x){int pos=start+sub+x,page=table[pos>>6];float w=__half2float(p[r*176+x]);a=fmaf(w,__half2float(v[kv_offset(page,kvh,pos&63,c)]),a);}s.o[d]+=a;}__syncthreads();}}
for(int i=tid;i<valid*128;i+=512){int r=i/128,d=i%128;out[(row0+r)*12*128+h*128+d]=__float2bfloat16_rn(s.o[r*128+d]/fmaxf(s.row_sum[r],1.e-24f));}}
int main(int argc,char**argv){if(argc!=2)return 2;int T=atoi(argv[1]);std::string p=std::string(NINFER_SOURCE_DIR)+"/experiments/E017-f6d-b4b-volta-d128-prefill/fixtures/history-"+std::to_string(T)+"/";auto load=[&](const char*n,void*d,size_t b){std::ifstream f(p+n,std::ios::binary);return f&&bool(f.read((char*)d,b));};int pages=2*((T+63)/64)+3;std::vector<unsigned short>q(T*12*128),k(pages*2*64*128),v(k.size());std::vector<int>tab((T+63)/64);std::vector<float>ref(T*12*128);if(!load("q.bf16",q.data(),q.size()*2)||!load("k_pages.bf16",k.data(),k.size()*2)||!load("v_pages.f16",v.data(),v.size()*2)||!load("block_table.i32",tab.data(),tab.size()*4)||!load("expected_f5a.f32",ref.data(),ref.size()*4))return 3;__nv_bfloat16*dq,*dk,*out;__half*dv;int*dt;cudaMalloc(&dq,q.size()*2);cudaMalloc(&dk,k.size()*2);cudaMalloc(&dv,v.size()*2);cudaMalloc(&out,ref.size()*2);cudaMalloc(&dt,tab.size()*4);cudaMemcpy(dq,q.data(),q.size()*2,cudaMemcpyHostToDevice);cudaMemcpy(dk,k.data(),k.size()*2,cudaMemcpyHostToDevice);cudaMemcpy(dv,v.data(),v.size()*2,cudaMemcpyHostToDevice);cudaMemcpy(dt,tab.data(),tab.size()*4,cudaMemcpyHostToDevice);standalone<<<dim3((T+31)/32,12),512,sizeof(SmemLayout)>>>(dq,dk,dv,out,dt,T);auto e=cudaDeviceSynchronize();if(e){std::cerr<<cudaGetErrorString(e)<<"\n";return 4;}std::vector<__nv_bfloat16>a(ref.size());cudaMemcpy(a.data(),out,a.size()*2,cudaMemcpyDeviceToHost);double e2=0,r2=0,mx=0;for(size_t i=0;i<a.size();++i){double z=__bfloat162float(a[i])-ref[i];e2+=z*z;r2+=ref[i]*ref[i];mx=fmax(mx,fabs(z));}std::cout<<"T="<<T<<" out="<<__bfloat162float(a[0])<<","<<__bfloat162float(a[1])<<","<<__bfloat162float(a[2])<<" ref="<<ref[0]<<","<<ref[1]<<","<<ref[2]<<" max="<<mx<<" rel="<<sqrt(e2/r2)<<"\n";}
